function maxHR(age, method){ return method==='tanaka'? 208-0.7*age : 220-age; }
function karvonen(age, hrRest, intensity, method){ var m=maxHR(age,method); return Math.round((m-hrRest)*intensity + hrRest); }
function zones(age, hrRest, method){ var edges=[0.5,0.6,0.7,0.8,0.9,1.0]; var z=[]; for(var i=1;i<edges.length;i++){ z.push({lo:karvonen(age,hrRest,edges[i-1],method), hi:karvonen(age,hrRest,edges[i],method)}); } return {max:maxHR(age,method), zones:z}; }
var EXPORTS={ maxHR:maxHR, karvonen:karvonen, zones:zones };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HeartZoneForgePure = EXPORTS; }
